#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
project_snapshot.py — Intelligent Diff-Aware Project Snapshot Generator (v2)

Purpose:
  Generates a complete, function-level-detailed snapshot of the project
  and compares it against the PREVIOUS run to show exactly what changed:
  which functions were added/removed/modified in which file, on which date.

  Designed for AI handoff: run this, copy the output (or the saved .md file),
  paste to any new AI assistant, and it will understand the ENTIRE history
  and current state of the project down to the function level.

Usage:
  python agents/project_snapshot.py

Outputs:
  - Terminal printout (copy-paste ready)
  - reports/latest_snapshot_for_ai.md      (overwritten each run)
  - project_history/CHANGELOG.md            (appended each run, permanent)
  - project_history/snapshots/snapshot_<timestamp>.json  (permanent archive)
  - project_history/latest_state.json       (used internally for next diff)
"""

import os
import ast
import json
import pickle
import hashlib
import traceback
from datetime import datetime, timezone
from pathlib import Path

# ============================================================
# ROADMAP DEFINITION (source of truth for project progress)
# ============================================================
