    {"step": 3, "name": "Persistent Label Registry",
     "file_marker": "persistent_knowledge/label_registry.pkl",
     "content_marker": None},
    {"step": 4, "name": "SLAM Map Annotator (Semi-Automatic)",
     "file_marker": "agents/slam_map_annotator.py", "content_marker": None},
    {"step": 5, "name": "Motive Video Annotator (.tak/NatNet)",
