def utc_now_iso():
    return datetime.now(tz=timezone.utc).isoformat()


def utc_now_stamp():
    return datetime.now(tz=timezone.utc).strftime("%Y-%m-%d_%H-%M-%S")


def find_project_root():
    """Auto-detect project root by walking up until agents/ + sessions/ found."""
    current = Path(__file__).resolve().parent
    for _ in range(6):
        if (current / "agents").is_dir() and (current / "sessions").is_dir():
            return current
        current = current.parent
    return Path.cwd()


# ============================================================
# LAYER 1: AST-based code structure fingerprinting
# ============================================================
class CodeStructureVisitor(ast.NodeVisitor):
    """Walks a Python AST and fingerprints every function/class."""

    def __init__(self, source_text):
        self.source_text = source_text
        self.functions = {}   # qualified_name -> {line_start, line_end, line_count, hash}
        self.classes = {}     # class_name -> {line_start, line_end, method_count, methods, hash}
        self._class_stack = []

    def _hash_segment(self, node):
        seg = ast.get_source_segment(self.source_text, node) or ""
        return hashlib.sha256(seg.encode("utf-8", "ignore")).hexdigest()[:12]

    def visit_ClassDef(self, node):
        self._class_stack.append(node.name)
        methods = [n.name for n in node.body
                   if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
        self.classes[node.name] = {
            "line_start": node.lineno,
            "line_end": getattr(node, "end_lineno", node.lineno),
            "method_count": len(methods),
            "methods": sorted(methods),
            "hash": self._hash_segment(node),
        }
        self.generic_visit(node)
        self._class_stack.pop()

    def _handle_function(self, node):
        qualname = (f"{self._class_stack[-1]}.{node.name}"
                    if self._class_stack else node.name)
        end = getattr(node, "end_lineno", node.lineno)
        self.functions[qualname] = {
            "line_start": node.lineno,
            "line_end": end,
            "line_count": end - node.lineno + 1,
            "hash": self._hash_segment(node),
        }

    def visit_FunctionDef(self, node):
        self._handle_function(node)
        self.generic_visit(node)

    visit_AsyncFunctionDef = visit_FunctionDef


def scan_python_file(filepath):
    """Extract full structural fingerprint of a .py file. Never raises."""
    record = {
        "size_kb": 0, "mtime": None, "line_count": 0,
        "sha256_full": None, "functions": {}, "classes": {},
        "module_docstring": None, "parse_error": None, "read_error": None,
    }
    try:
        stat = os.stat(filepath)
        record["size_kb"] = round(stat.st_size / 1024, 1)
        record["mtime"] = datetime.fromtimestamp(
            stat.st_mtime).strftime("%Y-%m-%d %H:%M:%S")
    except Exception as e:
        record["read_error"] = str(e)
        return record

    try:
        # utf-8-sig strips BOM automatically -> fixes U+FEFF crash files
        with open(filepath, "r", encoding="utf-8-sig") as f:
            source = f.read()
    except Exception as e:
        record["read_error"] = str(e)
        return record

    record["line_count"] = len(source.splitlines())
    record["sha256_full"] = hashlib.sha256(
        source.encode("utf-8", "ignore")).hexdigest()[:16]

    try:
        tree = ast.parse(source)
        record["module_docstring"] = ast.get_docstring(tree)
        visitor = CodeStructureVisitor(source)
        visitor.visit(tree)
        record["functions"] = visitor.functions
        record["classes"] = visitor.classes
    except SyntaxError as e:
        record["parse_error"] = f"line {e.lineno}: {e.msg}"
    except Exception as e:
        record["parse_error"] = f"unexpected: {e}"

    return record


def count_files_capped(dir_path, cap=50000):
    """Count files recursively, capped for performance safety."""
    count = 0
    try:
        for p in dir_path.rglob("*"):
            if p.is_file():
                count += 1
                if count >= cap:
                    return f"{cap}+"
    except Exception:
        return "?"
    return count


# ============================================================
# LAYER 2: Full project state builder
# ============================================================
def read_knowledge_summary(root):
    pkl_path = root / "persistent_knowledge" / "environment_knowledge.pkl"
    if not pkl_path.exists():
        return None
    try:
        with open(pkl_path, "rb") as f:
            data = pickle.load(f)
        objects = data.get("objects", [])
        names = []
        for o in objects:
            seen = o.get("names_seen")
            names.append(seen[0] if seen else o.get("object_id", "?"))
        return {
            "total_sessions": data.get("total_sessions_processed", 0),
            "last_updated": data.get("last_updated_utc", "unknown"),
            "object_count": len(objects),
            "object_names": sorted(names),
        }
    except Exception as e:
        return {"error": str(e)}


def read_deep_memory_summary(root):
    pkl_path = root / "persistent_knowledge" / "deep_learning_memory.pkl"
    if not pkl_path.exists():
        return None
    try:
        with open(pkl_path, "rb") as f:
            data = pickle.load(f)
        tracks = data.get("object_tracks", {})
        return {
            "sessions_analyzed": data.get("total_sessions_analyzed", 0),
            "object_track_names": sorted(list(tracks.keys())),
            "safety_events_count": len(data.get("safety_events", [])),
        }
    except Exception as e:
        return {"error": str(e)}


def check_roadmap_status(root):
    results = {}
    for step in ROADMAP:
        status = "NOT_STARTED"
        details = ""
        if step["file_marker"]:
            marker_path = root / step["file_marker"]
            if marker_path.exists():
                status = "DONE"
                if step["content_marker"]:
                    try:
                        with open(marker_path, "r", encoding="utf-8-sig",
                                  errors="ignore") as f:
                            content = f.read()
                        if step["content_marker"] not in content:
                            status = "PARTIAL"
                            details = (f"marker "
                                       f"'{step['content_marker']}' missing")
                    except Exception:
                        pass
            else:
                details = f"missing: {step['file_marker']}"
        else:
            status = "MANUAL_CHECK"
        results[str(step["step"])] = {
            "name": step["name"], "status": status, "details": details,
        }
    return results


def build_full_state(root):
    state = {
        "generated_at_utc": utc_now_iso(),
        "root": str(root),
        "agents": {},
        "sessions": {},
        "knowledge": None,
        "deep_memory": None,
        "roadmap": {},
    }

    agents_dir = root / "agents"
    if agents_dir.is_dir():
        for py_file in sorted(agents_dir.glob("*.py")):
            if py_file.name.startswith("__"):
                continue
            state["agents"][py_file.name] = scan_python_file(py_file)

    sessions_dir = root / "sessions"
    if sessions_dir.is_dir():
        for sess in sorted(sessions_dir.glob("session_*")):
            if not sess.is_dir():
                continue
            try:
                top_items = sorted([p.name for p in sess.iterdir()])
            except Exception:
                top_items = []
            state["sessions"][sess.name] = {
                "mtime": datetime.fromtimestamp(
                    sess.stat().st_mtime).strftime("%Y-%m-%d %H:%M:%S"),
                "has_fused_data": (sess / "fused_data.pkl").exists(),
                "has_comprehensive_report":
                    (sess / "session_comprehensive_report.txt").exists(),
                "has_pending_merge_candidate":
                    (sess / "pending_merge_candidate.pkl").exists(),
                "file_count": count_files_capped(sess),
                "top_level_items": top_items,
            }

    state["knowledge"] = read_knowledge_summary(root)
    state["deep_memory"] = read_deep_memory_summary(root)
    state["roadmap"] = check_roadmap_status(root)

    return state


# ============================================================
# LAYER 3: Diff engine (current vs previous run)
# ============================================================
def diff_named_items(old_items, new_items):
    """Generic diff for {name: {..., 'hash': X}} dicts (functions/classes)."""
    old_items = old_items or {}
    new_items = new_items or {}
    added, removed, modified = [], [], []
    for name, rec in new_items.items():
        if name not in old_items:
            added.append(name)
        elif old_items[name].get("hash") != rec.get("hash"):
            modified.append(name)
    for name in old_items:
        if name not in new_items:
            removed.append(name)
    return {"added": sorted(added), "removed": sorted(removed),
            "modified": sorted(modified)}


def diff_states(old, new):
    diff = {
        "first_run": old is None,
        "agents": {"new_files": [], "removed_files": [], "modified_files": {}},
        "sessions": {"new_sessions": [], "removed_sessions": []},
        "knowledge": {},
        "deep_memory": {},
        "roadmap_changes": [],
    }
    if old is None:
        return diff

    old_agents = old.get("agents", {}) or {}
    new_agents = new.get("agents", {}) or {}

    for fname, new_rec in new_agents.items():
        if fname not in old_agents:
            diff["agents"]["new_files"].append({
                "name": fname,
                "line_count": new_rec.get("line_count", 0),
                "function_count": len(new_rec.get("functions", {})),
            })
        else:
            old_rec = old_agents[fname]
            if old_rec.get("sha256_full") != new_rec.get("sha256_full"):
                func_diff = diff_named_items(old_rec.get("functions"),
                                              new_rec.get("functions"))
                class_diff = diff_named_items(old_rec.get("classes"),
                                               new_rec.get("classes"))
                diff["agents"]["modified_files"][fname] = {
                    "size_change_kb": round(
                        new_rec.get("size_kb", 0) -
                        old_rec.get("size_kb", 0), 2),
                    "line_change": (new_rec.get("line_count", 0) -
                                    old_rec.get("line_count", 0)),
                    "functions_added": func_diff["added"],
                    "functions_removed": func_diff["removed"],
                    "functions_modified": func_diff["modified"],
                    "classes_added": class_diff["added"],
                    "classes_removed": class_diff["removed"],
                    "classes_modified": class_diff["modified"],
                    "old_mtime": old_rec.get("mtime"),
                    "new_mtime": new_rec.get("mtime"),
                }

    for fname in old_agents:
        if fname not in new_agents:
            diff["agents"]["removed_files"].append(fname)

    old_sessions = set((old.get("sessions") or {}).keys())
    new_sessions = set((new.get("sessions") or {}).keys())
    diff["sessions"]["new_sessions"] = sorted(new_sessions - old_sessions)
    diff["sessions"]["removed_sessions"] = sorted(old_sessions - new_sessions)

    old_k = old.get("knowledge") or {}
    new_k = new.get("knowledge") or {}
    old_names = set(old_k.get("object_names", []) or [])
    new_names = set(new_k.get("object_names", []) or [])
    diff["knowledge"] = {
        "new_objects": sorted(new_names - old_names),
        "removed_objects": sorted(old_names - new_names),
        "session_count_change": (new_k.get("total_sessions", 0) -
                                  old_k.get("total_sessions", 0)),
    }

    old_d = old.get("deep_memory") or {}
    new_d = new.get("deep_memory") or {}
    diff["deep_memory"] = {
        "safety_events_change": (
            (new_d.get("safety_events_count") or 0) -
            (old_d.get("safety_events_count") or 0)),
        "sessions_analyzed_change": (
            (new_d.get("sessions_analyzed") or 0) -
            (old_d.get("sessions_analyzed") or 0)),
        "new_object_tracks": sorted(
            set(new_d.get("object_track_names", []) or []) -
            set(old_d.get("object_track_names", []) or [])),
    }

    old_r = old.get("roadmap", {}) or {}
    new_r = new.get("roadmap", {}) or {}
    for step, new_info in new_r.items():
        old_info = old_r.get(step)
        old_status = old_info["status"] if old_info else None
        if old_status != new_info["status"]:
            diff["roadmap_changes"].append({
                "step": step, "name": new_info["name"],
                "old_status": old_status or "UNKNOWN",
                "new_status": new_info["status"],
            })

    return diff


# ============================================================
# LAYER 4: History persistence (snapshots + changelog)
# ============================================================
def history_dir(root):
    d = root / "project_history"
    (d / "snapshots").mkdir(parents=True, exist_ok=True)
    return d


def load_previous_state(root):
    latest_path = history_dir(root) / "latest_state.json"
    if not latest_path.exists():
        return None
    try:
        with open(latest_path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def save_current_state(root, state):
    hdir = history_dir(root)
    latest_path = hdir / "latest_state.json"
    archive_path = hdir / "snapshots" / f"snapshot_{utc_now_stamp()}.json"
    try:
        with open(latest_path, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2, ensure_ascii=False, default=str)
        with open(archive_path, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2, ensure_ascii=False, default=str)
    except Exception as e:
        print(f"[snapshot] WARNING: could not save history state: {e}")


def append_changelog(root, diff):
    """Append a dated entry to the permanent CHANGELOG.md."""
    changelog_path = history_dir(root) / "CHANGELOG.md"
    lines = []
    lines.append(f"\n## {utc_now_iso()}\n")

    if diff.get("first_run"):
        lines.append("- 🆕 First run - baseline snapshot created.\n")
    else:
        a = diff["agents"]
        any_change = False

        for nf in a["new_files"]:
            any_change = True
            lines.append(f"- 🆕 NEW FILE: `{nf['name']}` "
                         f"({nf['line_count']} lines, "
                         f"{nf['function_count']} functions)\n")

        for rf in a["removed_files"]:
            any_change = True
            lines.append(f"- ❌ REMOVED FILE: `{rf}`\n")

        for fname, info in a["modified_files"].items():
            any_change = True
            parts = [f"- ✏️ MODIFIED: `{fname}` "
                    f"(lines {info['line_change']:+d}, "
                    f"size {info['size_change_kb']:+.1f}KB)"]
            if info["functions_added"]:
                parts.append(f"    - functions added: "
                             f"{', '.join(info['functions_added'])}")
            if info["functions_removed"]:
                parts.append(f"    - functions removed: "
                             f"{', '.join(info['functions_removed'])}")
            if info["functions_modified"]:
                parts.append(f"    - functions modified: "
                             f"{', '.join(info['functions_modified'])}")
            if info["classes_added"]:
                parts.append(f"    - classes added: "
                             f"{', '.join(info['classes_added'])}")
            if info["classes_modified"]:
                parts.append(f"    - classes modified: "
                             f"{', '.join(info['classes_modified'])}")
            lines.append("\n".join(parts) + "\n")

        if diff["sessions"]["new_sessions"]:
            any_change = True
            for s in diff["sessions"]["new_sessions"]:
                lines.append(f"- 🆕 New session: `{s}`\n")

        if diff["knowledge"].get("new_objects"):
            any_change = True
            lines.append(f"- 🧠 New objects learned: "
                         f"{diff['knowledge']['new_objects']}\n")

        if diff["deep_memory"].get("safety_events_change"):
            any_change = True
            lines.append(f"- ⚠️ Safety events change: "
                         f"{diff['deep_memory']['safety_events_change']:+d}\n")

        for rc in diff["roadmap_changes"]:
            any_change = True
            lines.append(f"- 🗺️ Step {rc['step']} ({rc['name']}): "
                         f"{rc['old_status']} → {rc['new_status']}\n")

        if not any_change:
            lines.append("- (no changes detected since last run)\n")

    entry = "".join(lines)
    with open(changelog_path, "a", encoding="utf-8") as f:
        f.write(entry)

    return entry


def read_last_changelog_entries(root, n=5):
    changelog_path = history_dir(root) / "CHANGELOG.md"
    if not changelog_path.exists():
        return "(no changelog yet)"
    try:
        with open(changelog_path, "r", encoding="utf-8") as f:
            content = f.read()
        entries = content.split("\n## ")
        entries = [e for e in entries if e.strip()]
        last = entries[-n:]
        rendered = "\n## ".join(last)
        if not rendered.startswith("##"):
            rendered = "## " + rendered
        return rendered
    except Exception as e:
        return f"(error reading changelog: {e})"


# ============================================================
# LAYER 5: Markdown report renderer
# ============================================================
def render_report(root, state, diff, changelog_entry, run_count):
    L = []
    L.append("=" * 70)
    L.append("  PROJECT SNAPSHOT FOR AI HANDOFF (v2 - Diff Aware)")
    L.append(f"  Generated: {state['generated_at_utc']}")
    L.append(f"  Root: {root}")
    L.append(f"  This is run #{run_count} of this tool.")
    L.append("=" * 70)

    # ---- WHAT CHANGED SINCE LAST RUN ----
    L.append("\n## 🆕 WHAT CHANGED SINCE LAST RUN")
    L.append("")
    if diff["first_run"]:
        L.append("  This is the FIRST run. No previous state to compare.")
        L.append("  A baseline has been created for future comparisons.")
    else:
        a = diff["agents"]
        changed_anything = False

        if a["new_files"]:
            changed_anything = True
            L.append("  🆕 New agent files:")
            for nf in a["new_files"]:
                L.append(f"     - {nf['name']} "
                         f"({nf['line_count']} lines, "
                         f"{nf['function_count']} functions)")

        if a["removed_files"]:
            changed_anything = True
            L.append("  ❌ Removed agent files:")
            for rf in a["removed_files"]:
                L.append(f"     - {rf}")

        if a["modified_files"]:
            changed_anything = True
            L.append("  ✏️ Modified agent files:")
            for fname, info in a["modified_files"].items():
                L.append(f"     - {fname}  "
                         f"(lines {info['line_change']:+d}, "
                         f"{info['old_mtime']} → {info['new_mtime']})")
                if info["functions_added"]:
                    L.append(f"         + functions added   : "
                             f"{', '.join(info['functions_added'])}")
                if info["functions_removed"]:
                    L.append(f"         - functions removed : "
                             f"{', '.join(info['functions_removed'])}")
                if info["functions_modified"]:
                    L.append(f"         ~ functions modified: "
                             f"{', '.join(info['functions_modified'])}")
                if info["classes_added"]:
                    L.append(f"         + classes added      : "
                             f"{', '.join(info['classes_added'])}")
                if info["classes_modified"]:
                    L.append(f"         ~ classes modified   : "
                             f"{', '.join(info['classes_modified'])}")

        if diff["sessions"]["new_sessions"]:
            changed_anything = True
            L.append("  🆕 New sessions recorded:")
            for s in diff["sessions"]["new_sessions"]:
                L.append(f"     - {s}")

        if diff["knowledge"].get("new_objects"):
            changed_anything = True
            L.append(f"  🧠 New objects learned: "
                     f"{diff['knowledge']['new_objects']}")

        dm = diff["deep_memory"]
        if dm.get("safety_events_change"):
            changed_anything = True
            L.append(f"  ⚠️ Safety events count change: "
                     f"{dm['safety_events_change']:+d}")
        if dm.get("new_object_tracks"):
            changed_anything = True
            L.append(f"  🎯 New object tracks in deep memory: "
                     f"{dm['new_object_tracks']}")

        if diff["roadmap_changes"]:
            changed_anything = True
            L.append("  🗺️ Roadmap status changes:")
            for rc in diff["roadmap_changes"]:
                L.append(f"     - Step {rc['step']} ({rc['name']}): "
                         f"{rc['old_status']} → {rc['new_status']}")

        if not changed_anything:
            L.append("  (No changes detected since the last run of this "
                     "tool.)")

    # ---- ROADMAP STATUS ----
    L.append("\n## 🗺️ ROADMAP STATUS (current)")
    L.append("")
    for step_str, info in sorted(state["roadmap"].items(), key=lambda x: int(x[0])):
        icon = {"DONE": "✅", "PARTIAL": "🟡", "NOT_STARTED": "⏳",
                "MANUAL_CHECK": "❓"}.get(info["status"], "❓")
        L.append(f"  Step {step_str:>2}. {icon} {info['status']:<14} "
                 f"{info['name']}")
        if info["details"]:
            L.append(f"          └─ {info['details']}")

    pending = [s for s, i in state["roadmap"].items()
               if i["status"] in ("NOT_STARTED", "PARTIAL")]
    if pending:
        first_pending = min(pending, key=int)
        L.append(f"\n  👉 CURRENT FOCUS: Step {first_pending} — "
                 f"{state['roadmap'][first_pending]['name']}")

    # ---- FULL AGENT INVENTORY ----
    L.append("\n## 🤖 FULL AGENTS INVENTORY (current structural detail)")
    L.append("")
    L.append(f"  Total agent files: {len(state['agents'])}")
    for fname, rec in sorted(state["agents"].items()):
        L.append(f"\n  📄 {fname}")
        L.append(f"     size: {rec['size_kb']}KB | lines: "
                 f"{rec['line_count']} | modified: {rec['mtime']}")
        if rec.get("read_error"):
            L.append(f"     ⚠️ READ ERROR: {rec['read_error']}")
            continue
        if rec.get("parse_error"):
            L.append(f"     ⚠️ SYNTAX ERROR: {rec['parse_error']}")
        if rec.get("module_docstring"):
            first_line = rec["module_docstring"].strip().split("\n")[0]
            L.append(f"     purpose: {first_line}")
        L.append(f"     functions: {len(rec.get('functions', {}))} | "
                 f"classes: {len(rec.get('classes', {}))}")

    # ---- SESSIONS ----
    L.append("\n## 📁 SESSIONS")
    L.append("")
    sessions = state["sessions"]
    L.append(f"  Total sessions: {len(sessions)}")
    for sname, srec in sorted(sessions.items()):
        L.append(f"  - {sname}  (files: {srec['file_count']}, "
                 f"fused: {'✅' if srec['has_fused_data'] else '❌'}, "
                 f"report: {'✅' if srec['has_comprehensive_report'] else '❌'})")

    # ---- KNOWLEDGE ----
    L.append("\n## 🧠 PERSISTENT KNOWLEDGE")
    L.append("")
    k = state["knowledge"]
    if k:
        if "error" in k:
            L.append(f"  ⚠️ Error: {k['error']}")
        else:
            L.append(f"  Sessions processed: {k['total_sessions']}")
            L.append(f"  Known objects     : {k['object_count']} "
                     f"{k['object_names']}")
            L.append(f"  Last updated      : {k['last_updated']}")
    else:
        L.append("  (not yet created)")

    d = state["deep_memory"]
    L.append("\n  Deep Learning Memory:")
    if d:
        if "error" in d:
            L.append(f"    ⚠️ Error: {d['error']}")
        else:
            L.append(f"    Sessions analyzed: {d['sessions_analyzed']}")
            L.append(f"    Object tracks    : {d['object_track_names']}")
            L.append(f"    Safety events    : {d['safety_events_count']}")
    else:
        L.append("    (not yet created)")

    # ---- RECENT HISTORY TIMELINE ----
    L.append("\n## 📅 RECENT CHANGE HISTORY (last few runs)")
    L.append("")
    L.append(read_last_changelog_entries(root, n=5))

    # ---- INSTRUCTIONS FOR AI ----
    L.append("\n## 💬 INSTRUCTIONS FOR NEW AI")
    L.append("")
    L.append("  Kiarash is building a VLA (Vision-Language-Action) dataset")
    L.append("  pipeline for a MiR robot using OptiTrack Motive + SLAM data.")
    L.append("")
    L.append("  - Read 'WHAT CHANGED SINCE LAST RUN' to see recent progress.")
    L.append("  - Read 'ROADMAP STATUS' + 'CURRENT FOCUS' to know next step.")
    L.append("  - Read 'RECENT CHANGE HISTORY' for the last few sessions'")
    L.append("    worth of development timeline.")
    L.append("")
    L.append("  Key principles (never violate):")
    L.append("    1. NEVER auto-merge to deep memory (human approves only)")
    L.append("    2. NEVER assume - always ask if uncertain")
    L.append("    3. Python 3.10 - NO backslash inside f-string expressions")
    L.append("    4. Small surgical changes, never rewrite working code")
    L.append("    5. Final product language = English (chat = Persian)")

    L.append("\n" + "=" * 70)
    L.append("  END OF SNAPSHOT")
    L.append("=" * 70)

    return "\n".join(L)


# ============================================================
# MAIN
# ============================================================
def main():
    root = find_project_root()
    print(f"[snapshot] Project root: {root}")

    old_state = load_previous_state(root)
    run_count_path = history_dir(root) / "run_count.txt"
    run_count = 1
    if run_count_path.exists():
        try:
            run_count = int(run_count_path.read_text().strip()) + 1
        except Exception:
            run_count = 1
    run_count_path.write_text(str(run_count), encoding="utf-8")

    print("[snapshot] Scanning project structure (this may take a moment)...")
    new_state = build_full_state(root)

    print("[snapshot] Computing diff against previous run...")
    diff = diff_states(old_state, new_state)

    print("[snapshot] Appending to permanent changelog...")
    changelog_entry = append_changelog(root, diff)

    print("[snapshot] Saving new state as baseline for next run...")
    save_current_state(root, new_state)

    report = render_report(root, new_state, diff, changelog_entry, run_count)

    print("\n" + report)

    reports_dir = root / "reports"
    reports_dir.mkdir(exist_ok=True)
    out_path = reports_dir / "latest_snapshot_for_ai.md"
    try:
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(report)
        print(f"\n[snapshot] Saved to: {out_path}")
        print(f"[snapshot] Permanent changelog: "
             f"{history_dir(root) / 'CHANGELOG.md'}")
        print("[snapshot] Copy the output above (or the .md file) and "
             "paste to any new AI.")
    except Exception as e:
        print(f"\n[snapshot] WARNING: could not save report file: {e}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        print("[snapshot] FATAL ERROR:")
        traceback.print_exc()

