        lines.append("### New sessions")
        for name in diff["sessions_added"]:
            lines.append(f"- `{name}`")

    if diff["motive_files_added"]:
        lines.append("")
        lines.append("### New Motive files")
        for name in diff["motive_files_added"]:
            lines.append(f"- `{name}`")

    lines.append("")
    lines.append("## 3. Current Roadmap")
    lines.append("")

    current_focus = None

    for step in sorted(state["roadmap"], key=int):
        item = state["roadmap"][step]
        icon = {
            "DONE": "DONE",
            "PARTIAL": "PARTIAL",
            "NOT_STARTED": "NOT STARTED",
        }.get(item["status"], item["status"])

        lines.append(
            f"- Step {step}: **{icon}** — {item['name']} "
            f"({item['evidence_passed']}/{item['evidence_total']} "
            f"evidence checks)"
        )
        lines.append(f"  - Goal: {item['intent']}")

        if current_focus is None and item["status"] != "DONE":
            current_focus = (step, item["name"])

    if current_focus:
        lines.append("")
        lines.append(
            f"**Current roadmap focus:** Step {current_focus[0]} — "
            f"{current_focus[1]}"
        )

    lines.append("")
    lines.append("## 4. Full Agent Inventory")
    lines.append("")

    for name, record in sorted(state["agents"].items()):
        plan = AGENT_PLANS.get(name, {})
        docstring = record.get("module_docstring") or ""
        purpose = docstring.strip().splitlines()[0] if docstring else "Unknown"

        lines.append(f"### `{name}`")
        lines.append(f"- Category: {plan.get('category', 'Unclassified')}")
        lines.append(f"- Declared purpose: {purpose}")
        lines.append(
            f"- Current role: {plan.get('current', 'Infer from source and documentation.')}"
        )
        lines.append(
            f"- Future direction: {plan.get('future', 'Must be documented before expansion.')}"
        )
        lines.append(f"- Lines: {record.get('line_count', 0)}")
        lines.append(f"- SHA-256: `{record.get('sha256_full')}`")
        lines.append(
            f"- Parse error: {record.get('parse_error') or 'None'}"
        )

        functions = sorted(record.get("functions", {}))
        classes = sorted(record.get("classes", {}))
        imports = record.get("imports", [])

        lines.append(f"- Functions ({len(functions)}): {functions}")
        lines.append(f"- Classes ({len(classes)}): {classes}")
        lines.append(f"- Imports: {imports}")
        lines.append("")

    lines.append("## 5. Runtime Integration Evidence")
    lines.append("")

    references = state["integration_references"]

    lines.append("### MiR/ROS/API references found")
    if references["robot_api"]:
        for item in references["robot_api"]:
            lines.append(
                f"- `{item['file']}:{item['line']}` — `{item['text']}`"
            )
    else:
        lines.append(
            "- No clear MiR/ROS API reference was detected outside "
            "diagnostic/snapshot files."
        )

    lines.append("")
    lines.append("### Motive/NatNet references found")
    if references["motive_natnet"]:
        for item in references["motive_natnet"]:
            lines.append(
                f"- `{item['file']}:{item['line']}` — `{item['text']}`"
            )
    else:
        lines.append("- No Motive/NatNet reference detected.")

    lines.append("")
    lines.append("## 6. Session Inventory")
    lines.append("")

    for name, record in sorted(state["sessions"].items()):
        lines.append(f"### `{name}`")
        lines.append(f"- Fused data: {record['has_fused_data']}")
        lines.append(f"- Comprehensive report: {record['has_report']}")
        lines.append(
            f"- Pending merge candidate: "
            f"{record['has_pending_candidate']}"
        )
        lines.append(
            f"- Artifacts ({len(record['artifacts'])}): "
            f"{sorted(record['artifacts'])}"
        )

    lines.append("")
    lines.append("## 7. Motive File Inventory")
    lines.append("")

    grouped = {}
    for name, record in state["motive_files"].items():
        grouped.setdefault(record["session_id"], []).append((name, record))

    for session_id, items in sorted(grouped.items()):
        lines.append(f"### `{session_id}`")
        for name, record in items:
            size_mb = record["size_bytes"] / (1024 * 1024)
            lines.append(
                f"- `{name}` — {record['extension']}, "
                f"{size_mb:.2f} MB, modified {record['mtime']}"
            )

    lines.append("")
    lines.append("## 8. Persistent Knowledge")
    lines.append("")

    lines.append("### Environment knowledge")
    lines.append(
        json.dumps(
            state["environment_knowledge"],
            indent=2,
            ensure_ascii=False,
        )
    )

    lines.append("")
    lines.append("### Deep learning memory")
    lines.append(
        json.dumps(
            state["deep_memory"],
            indent=2,
            ensure_ascii=False,
        )
    )

    lines.append("")
    lines.append("## 9. Project-History Documents")
    lines.append("")

    documents = state["history_documents"]

    if not documents:
        lines.append("No manual history document was found.")
    else:
        for name, record in sorted(documents.items()):
            lines.append(f"### `{name}`")

            if "read_error" in record:
                lines.append(f"Read error: {record['read_error']}")
                continue

            lines.append(
                f"- Lines: {record['line_count']}"
            )
            lines.append(
                f"- Modified: {record['metadata']['mtime']}"
            )
            lines.append(
                f"- SHA-256: `{record['sha256']}`"
            )
            lines.append("")

            content = record["content"]
            if len(content) > MAX_HISTORY_DOCUMENT_CHARS:
                hidden = len(content) - MAX_HISTORY_DOCUMENT_CHARS
                content = content[:MAX_HISTORY_DOCUMENT_CHARS]
                content += (
                    f"\n\n[... {hidden} characters truncated; "
                    f"read project_history/{name} directly ...]"
                )

            lines.append(content)
            lines.append("")

    lines.append("## 10. Latest Comprehensive Session Report")
    lines.append("")

    latest_report = state["latest_session_report"]

    if latest_report:
        lines.append(f"Source: `{latest_report['path']}`")
        lines.append("")
        lines.append("```text")
        lines.append(latest_report["content"])
        lines.append("```")
    else:
        lines.append("No comprehensive session report found.")

    lines.append("")
    lines.append("## 11. Known Open Issues and Blockers")
    lines.append("")
    lines.append(
        "- The real multi-row schema of the Motive CSV has not yet "
        "been inspected."
    )
    lines.append(
        "- Camera descriptions/intrinsics/extrinsics have not yet "
        "been empirically verified."
    )
    lines.append(
        "- A clean way to project Motive world coordinates into each "
        "AVI camera is not yet confirmed."
    )
    lines.append(
        "- The exact MiR API/ROS acquisition module must be identified."
    )
    lines.append(
        "- Persistent Label Registry must be implemented before "
        "cross-source automatic label suggestions."
    )
    lines.append(
        "- Persistent environment knowledge reports 2 processed "
        "sessions while deep memory reports 1 analyzed session; "
        "the semantic difference must be documented."
    )

    lines.append("")
    lines.append("## 12. Rules for the Next AI")
    lines.append("")
    lines.append("1. Never auto-merge into permanent deep memory.")
    lines.append("2. Default answer to all destructive operations is no.")
    lines.append("3. Do not invent a CSV schema or camera calibration.")
    lines.append("4. Keep Motive API and MiR API in separate connectors.")
    lines.append("5. Use Python 3.10-compatible syntax.")
    lines.append("6. Prefer small, reversible and syntax-verified changes.")
    lines.append(
        "7. Suggestions from cross-reference are never final until "
        "human-confirmed."
    )
    lines.append(
        "8. Full annotations belong in JSONL; comprehensive reports "
        "contain summaries and traceable file references."
    )
    lines.append(
        "9. Training is dual-source redundant: Motive and SLAM are "
        "both first-class modalities."
    )

    return "\n".join(lines)


def main():
    root = find_project_root()
    print(f"[snapshot] Project root: {root}")

    previous_state = load_previous_state(root)

    print("[snapshot] Scanning project...")
    current_state = build_state(root)

    print("[snapshot] Comparing with previous state...")
    diff = compare_states(previous_state, current_state)

    documents = current_state.get("history_documents", {})
    added_documents = set(diff["history_documents"]["added"])
    modified_documents = set(
        diff["history_documents"]["modified"]
    )

    for name in sorted(documents):
        if name in added_documents:
            print(
                f"[snapshot] NEW HISTORY DOCUMENT READ: {name}"
            )
        elif name in modified_documents:
            print(
                f"[snapshot] HISTORY DOCUMENT UPDATED AND READ: {name}"
            )
        else:
            print(f"[snapshot] HISTORY DOCUMENT READ: {name}")

    run_number = next_run_number(root)
    report = render_report(
        root,
        current_state,
        diff,
        run_number,
    )

    reports_directory = root / "reports"
    reports_directory.mkdir(parents=True, exist_ok=True)

    report_path = (
        reports_directory / "latest_snapshot_for_ai.md"
    )
    report_path.write_text(report, encoding="utf-8")

    append_changelog(root, diff)
    save_state(root, current_state)

    print("")
    print(report)
    print("")
    print(f"[snapshot] Snapshot saved: {report_path}")
    print(
        f"[snapshot] Permanent changelog: "
        f"{history_directory(root) / 'CHANGELOG.md'}"
    )


if __name__ == "__main__":
    try:
        main()
    except Exception:
        print("[snapshot] FATAL ERROR")
        traceback.print_exc()
        raise
